import itertools
import random
import json
import sys
from pathlib import Path

# Import the reduction and problem definitions
import reduce
from problems import ThreeColoring, OneInThreeSat


def three_coloring_bruteforce(instance):
    n = instance["n"]
    edges = instance["edges"]
    for coloring in itertools.product(range(3), repeat=n):
        ok = True
        for u, v in edges:
            if coloring[u] == coloring[v]:
                ok = False
                break
        if ok:
            return True
    return False


def one_in_three_sat_bruteforce(instance):
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for assignment in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            true_count = sum(assignment[abs(lit)-1] for lit in clause)
            if true_count != 1:
                ok = False
                break
        if ok:
            return True
    return False


def generate_random_graph(n, edge_prob=0.5):
    edges = []
    for u in range(n):
        for v in range(u+1, n):
            if random.random() < edge_prob:
                edges.append([u, v])
    return {"n": n, "edges": edges}


def main():
    random.seed(0)
    total = 0
    passed = 0
    for n in range(0, 5):  # up to 4 vertices
        # generate all graphs for n up to 4 (there are 2^{n choose 2})
        verts = list(range(n))
        possible_edges = [(u, v) for u in verts for v in verts if u < v]
        for mask in range(1 << len(possible_edges)):
            edges = []
            for i, (u, v) in enumerate(possible_edges):
                if mask & (1 << i):
                    edges.append([u, v])
            instance = {"n": n, "edges": edges}
            # validate source
            ThreeColoring.validate(instance)
            # compute answers
            ans_src = three_coloring_bruteforce(instance)
            red = reduce.reduce(instance)
            # validate target
            OneInThreeSat.validate(red)
            ans_tgt = one_in_three_sat_bruteforce(red)
            total += 1
            if ans_src == ans_tgt:
                passed += 1
            else:
                print("Mismatch!", instance, red)
                sys.exit(1)
    print(f"All {total} tests passed: {passed}/{total}")
    # write verdict
    verdict = {"verified": True, "tests_run": total, "tests_passed": passed}
    Path('verdict.json').write_text(json.dumps(verdict))

if __name__ == "__main__":
    main()
EOF"}

